const raw = $input.first().json;
const b = raw.body || raw;
const headers = raw.headers || {};
// Forward site secret from inbound webhook header (do NOT use $env — denied on multi-tenant n8n)
const toroSecret = headers['x-toro-secret'] || headers['X-Toro-Secret'] || headers['x-lead-secret'] || '';

const firstName = (b.firstName || (b.name || 'there').toString().split(/\s+/)[0] || 'there').trim();
const stage = b.stage || (b.event === 'stage_changed' ? b.stage : 'newLead') || 'newLead';
let delayed = Array.isArray(b.delayedSteps) ? b.delayedSteps : [];

// Fallback for new leads without delayedSteps (older callers)
if (!delayed.length && (b.event === 'crm_lead' || b.event === 'funnel_submit' || !b.event)) {
  delayed = [
    { id: 'new_1h', delayMinutes: 60, channel: 'both' },
    { id: 'new_24h', delayMinutes: 1440, channel: 'both' },
    { id: 'new_72h', delayMinutes: 4320, channel: 'both' }
  ];
}

if (!delayed.length) {
  return [{ json: { skip: true, reason: 'no delayed steps', stage, firstName } }];
}

return delayed
  .filter((s) => s && s.id && Number(s.delayMinutes) > 0)
  .sort((a, b) => Number(a.delayMinutes) - Number(b.delayMinutes))
  .map((step) => ({
    json: {
      skip: false,
      firstName,
      email: (b.email || '').trim(),
      phone: (b.phone || '').trim(),
      lang: b.lang === 'es' ? 'es' : 'en',
      stage,
      consentSms: !!(b.consentSms || b.smsConsent || b.smsOptIn),
      consentEmail: b.consentEmail !== false,
      stepId: step.id,
      delayMinutes: Number(step.delayMinutes) || 60,
      channel: step.channel || 'both',
      base: 'https://toromovers.net',
      event: b.event || 'crm_lead',
      toroSecret
    }
  }));
